use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},io::Read};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn receipt(p:&Path){let e=read(p.join("exit.json"));assert_eq!(e["success"],true,"{}",p.display());assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{s}.log"))),e[format!("{s}_sha256")].as_str().unwrap());}}
fn median(v:&[f64])->f64{let mut v=v.to_vec();assert!(!v.is_empty()&&v.iter().all(|x|x.is_finite()));v.sort_by(f64::total_cmp);v[v.len()/2]}
fn main(){let r=Path::new("/tmp/zopro-front-end-counters");assert_eq!(read(r.join("capture/result.json"))["status"],"complete");let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("capture-pins.json"))).unwrap();assert_eq!(pins.len(),697);for(p,h)in &pins{assert_eq!(hash(p),*h,"pin{p}");}
 let order=read(r.join("capture-order.json"));assert_eq!(order.as_array().unwrap().len(),27);let prior:BTreeSet<String>=serde_json::from_value(read(r.join("prior-proof-sha256.json"))).unwrap();let old=read("/tmp/zopro-streamed-complex-sdk/perf-plan.json");let expected=old["cases"].as_array().unwrap().iter().map(|c|(c["shape"].as_str().unwrap().to_owned(),c["public_sha256"].as_str().unwrap().to_owned())).collect::<BTreeMap<_,_>>();let mut proofs=BTreeSet::new();let mut inventory=BTreeMap::new();let mut rows=Vec::new();let mut samples=0;let mut calls=0;let mut running_min=100f64;
 for row in order.as_array().unwrap(){let name=row["name"].as_str().unwrap();let dir=r.join("capture").join(name);receipt(&dir);let rounds=row["case"]["rounds"].as_u64().unwrap();let workers=row["case"]["workers"].as_u64().unwrap();let shape=row["case"]["shape"].as_str().unwrap();let out=fs::read_to_string(dir.join("stdout.log")).unwrap();let ss=out.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(ss.len()as u64,rounds);for(i,s)in ss.iter().enumerate(){assert_eq!(s["round"],i as u64);let ms=s["ms"].as_f64().unwrap();assert!(ms.is_finite()&&ms>0.);}
 let summaries=out.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).collect::<Vec<_>>();assert_eq!(summaries.len(),1);let summary:Value=serde_json::from_str(summaries[0]).unwrap();assert_eq!(summary["rounds"],rounds);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],workers);samples+=rounds;calls+=rounds+3;
 let text=fs::read_to_string(row["csv"].as_str().unwrap()).unwrap();let entries=text.lines().filter(|l|!l.trim().is_empty()&&!l.starts_with('#')).filter_map(|l|{let f=l.split(';').collect::<Vec<_>>();if f.len()<5{return None;}let count=f[0].trim().parse::<f64>().expect("unsupported counter");let enabled=f[3].trim().parse::<u64>().unwrap();let running=f[4].trim().parse::<f64>().unwrap();assert!(count.is_finite()&&count>=0.&&enabled>0&&running>=99.);running_min=running_min.min(running);Some(json!({"event":f[2],"count":count,"enabled_ns":enabled,"running_percent":running}))}).collect::<Vec<_>>();assert_eq!(entries.len(),4);for(i,e)in entries.iter().enumerate(){assert_eq!(e["event"],row["events"][i]);assert_eq!(e["enabled_ns"],entries[0]["enabled_ns"]);}let cycles=entries[0]["count"].as_f64().unwrap();assert!(cycles>0.);let c=|i:usize|entries[i]["count"].as_f64().unwrap();let mut metrics=BTreeMap::new();let panel=row["panel"].as_str().unwrap();match panel{
 "slots"=>{for(key,i)in[("frontend_empty_slot_fraction",1),("backend_blocked_slot_fraction",2),("smt_denied_slot_fraction",3)]{let x=c(i)/(8.*cycles);assert!((0.0..=1.0).contains(&x),"invalidslotfraction{name}{key}{x}");metrics.insert(key,x);}},
 "ops"=>{metrics.insert("retired_macroop_slot_fraction",c(1)/(8.*cycles));metrics.insert("dispatched_op_slot_fraction",c(2)/(8.*cycles));metrics.insert("dispatched_minus_retired_slot_fraction",(c(2)-c(1))/(8.*cycles));metrics.insert("instructions_per_user_cycle",c(3)/cycles);},
 "fetch"=>{metrics.insert("frontend_at_least_eight_empty_slots_cycle_fraction",c(1)/cycles);metrics.insert("icache_l2_fill_lines_per_1000_user_cycles",c(2)*1000./cycles);metrics.insert("icache_system_fill_lines_per_1000_user_cycles",c(3)*1000./cycles);},_=>unreachable!()}
 let vdir=r.join("capture").join(format!("gnark-{name}"));receipt(&vdir);assert_eq!(fs::read_to_string(vdir.join("stdout.log")).unwrap().lines().last().unwrap().trim(),"verified 1 distinct proofs across 1 pinned keys");let proofdir=Path::new(row["proof"].as_str().unwrap());let proof=proofdir.join("0.proof");let public=proofdir.join("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);let digest=hash(&proof);assert!(!prior.contains(&digest));assert!(proofs.insert(digest.clone()));assert_eq!(hash(&public),expected[shape]);inventory.insert(proof.to_str().unwrap().to_owned(),digest);inventory.insert(public.to_str().unwrap().to_owned(),hash(&public));
 for p in[&proof,&public]{pins.insert(p.to_str().unwrap().into(),hash(p));}let csv=Path::new(row["csv"].as_str().unwrap());pins.insert(csv.to_str().unwrap().into(),hash(csv));for root in[dir,vdir]{for n in["command.json","exit.json","stdout.log","stderr.log"]{let p=root.join(n);pins.insert(p.to_str().unwrap().into(),hash(&p));}}
 let user=summary["user_cpu_ms"].as_f64().unwrap();let system=summary["system_cpu_ms"].as_f64().unwrap();rows.push(json!({"name":name,"block":row["block"],"case":row["case"],"panel":panel,"counters":entries,"metrics":metrics,"sdk_summary":summary,"diagnostic_median_ms":median(&ss.iter().map(|s|s["ms"].as_f64().unwrap()).collect::<Vec<_>>()),"user_system_cpu_ms_per_request":(user+system)/rounds as f64,"proof_sha256":hash(proof),"public_sha256":hash(public),"cycles_per_request":cycles/rounds as f64}));}
 assert_eq!(samples,5571);assert_eq!(calls,5652);assert_eq!(proofs.len(),27);assert_eq!(inventory.len(),54);let mut cases=BTreeMap::new();for case in["primary32","primary16","merge54"]{let selected=rows.iter().filter(|row|row["case"]["name"]==case).collect::<Vec<_>>();assert_eq!(selected.len(),9);let mut panels=BTreeMap::new();for panel in["slots","ops","fetch"]{let p=selected.iter().filter(|r|r["panel"]==panel).collect::<Vec<_>>();assert_eq!(p.len(),3);let keys=p[0]["metrics"].as_object().unwrap().keys().cloned().collect::<Vec<_>>();let med=keys.iter().map(|key|(key.clone(),median(&p.iter().map(|v|v["metrics"][key].as_f64().unwrap()).collect::<Vec<_>>()))).collect::<BTreeMap<_,_>>();panels.insert(panel,json!({"metrics_median":med,"blocks":p.iter().map(|p|p["name"].clone()).collect::<Vec<_>>(),"diagnostic_median_ms":median(&p.iter().map(|p|p["diagnostic_median_ms"].as_f64().unwrap()).collect::<Vec<_>>()),"cpu_ms_per_request_median":median(&p.iter().map(|p|p["user_system_cpu_ms_per_request"].as_f64().unwrap()).collect::<Vec<_>>())}));}cases.insert(case,json!({"panels":panels}));}
 save(r.join("rows.json"),&json!(rows));save(r.join("proof-inventory.json"),&json!(inventory));let result=json!({"status":"closed_verified","cases":cases,"input_pins_rehashed":697,"final_pins":pins.len(),"captured_processes":27,"counter_panels_per_case":3,"blocks":3,"minimum_running_percent":running_min,"nonmultiplexed":running_min==100.,"timed_diagnostic_sdk_calls":samples,"priming_sdk_calls":81,"total_sdk_calls":calls,"distinct_independent_gnark_exports":27,"proof_public_members":54,"prior_proof_identities":prior.len(),"all_public_fixture_hashes_match":true,"all_proofs_fresh_and_164_bytes":true,"accepted_170_sources_and_sdk_unchanged":true,"adopted":false,"goal_achieved":false,"scope":"Whole warm SDK dispatch counters, not loop-specific bottleneck, causal stalls, latency qualification or predicted speedup. Independent panels are not a single jointly measured decomposition; thread-slot ratios are not physical-core occupancy."});save(r.join("analysis.json"),&result);save(r.join("closeout-pins.json"),&json!(pins));println!("CLOSED27captures5652SDK27Gnark54members;697inputpins; running{running_min}%");for(case,value)in result["cases"].as_object().unwrap(){println!("{case} {}",value["panels"]);} }
